/// What Playarr knows about a song for mixing it. Times in seconds from the start of the song.
public struct MixMap: Codable, Hashable, Sendable {
    public var version: Int
    public var duration: Double
    /// Beats per minute of the grid (not folded: a 174 BPM song stays 174).
    public var bpm: Double
    /// Time of the first beat of the grid; beat n is at firstBeat + n * 60 / bpm.
    public var firstBeat: Double
    /// Beats from firstBeat to the music's first downbeat, 0–3 (analysis moves firstBeat to the grid beat up to three beats before that downbeat, so it never needs more). Bars start there and every 4 beats after; phrases every 16.
    public var downbeatOffset: Double
    /// 0–1: how sure the bar and phrase starts are (the bar's confidence times the phrase's: a fade-in with no drop to go by leaves the phrase start unsure). Below 0.4 the planner doesn't trust phrase alignment (no long blend; quick mixes land on a beat). Missing counts as sure.
    public var downbeatConfidence: Double?
    /// The grid holds over the whole song (no wandering tempo): long blends allowed. Read it together with `beatConfidence`: it is false whenever the confidence is below 0.35 (noise, beatless music).
    public var gridStable: Bool
    /// 0–1: how sure the beat grid is.
    public var beatConfidence: Double
    public var key: Key?
    /// Seconds from the start with a steady beat and little else: where the song can be brought in.
    public var introEnd: Double
    /// Seconds from the start where the outro begins (beat-led, sparse): where the song can be left.
    public var outroStart: Double
    /// The first big rise in energy, if any.
    public var firstDrop: Double?
    /// The song starts on full sound (no fade or intro), or ends on it (abruptly, not faded out). Full sound: about as loud as the main part of the song, and more than a kick on its own.
    public var coldStart: Bool
    public var coldEnd: Bool
    /// Where sound starts (after leading silence). Missing in maps from before version 4: 0.
    public var soundStart: Double?
    /// Where sound ends (before trailing silence).
    public var soundEnd: Double
    /// What found the beats and bars: the beat model (Beat This!, on the server), or the onset analysis when the model couldn't run. Missing in maps from before the model.
    public var beatsFrom: BeatsFrom?
    /// Energy 0–1 per 16-beat phrase, relative to the loudest: phraseEnergy[k] is the phrase from phrase line k (firstBeat + (downbeatOffset + 16k) beats), the first line being the music's first phrase start. Over the whole song (a long song's middle measured for its loudness alone); null for a phrase that wasn't measured (maps from before version 8 end after a long song's first 7 minutes).
    public var phraseEnergy: [Double?]
    /// How far the beat strays in each 16-beat phrase (same phrase lines as phraseEnergy, but over the whole song), in ms: the median offset of the beat model's beats in the phrase from the grid, less the song's (so a beat sitting a little off the grid all through counts as steady). Null: too few beats to tell (a breakdown without one), or a long song's middle, which isn't analysed. Read with beatHolds, which judges just the phrases a mix covers; from version 6, and only from the beat model.
    public var phraseDrift: [Double?]?
    /// The beat holds where the song is mixed: over the 64 beats before its intro ends and the 64 from its outro's start (see phraseDrift). What blend scores go by; from version 6, with phraseDrift.
    public var edgesStable: Bool?

    public init(version: Int, duration: Double, bpm: Double, firstBeat: Double, downbeatOffset: Double, downbeatConfidence: Double? = nil, gridStable: Bool, beatConfidence: Double, key: Key? = nil, introEnd: Double, outroStart: Double, firstDrop: Double? = nil, coldStart: Bool, coldEnd: Bool, soundStart: Double? = nil, soundEnd: Double, beatsFrom: BeatsFrom? = nil, phraseEnergy: [Double?], phraseDrift: [Double?]? = nil, edgesStable: Bool? = nil) {
        self.version = version
        self.duration = duration
        self.bpm = bpm
        self.firstBeat = firstBeat
        self.downbeatOffset = downbeatOffset
        self.downbeatConfidence = downbeatConfidence
        self.gridStable = gridStable
        self.beatConfidence = beatConfidence
        self.key = key
        self.introEnd = introEnd
        self.outroStart = outroStart
        self.firstDrop = firstDrop
        self.coldStart = coldStart
        self.coldEnd = coldEnd
        self.soundStart = soundStart
        self.soundEnd = soundEnd
        self.beatsFrom = beatsFrom
        self.phraseEnergy = phraseEnergy
        self.phraseDrift = phraseDrift
        self.edgesStable = edgesStable
    }

