/// POST /api/files/:fileId/rematch: what matching a file on MusicBrainz again did.
public enum RematchResult: Codable, Hashable, Sendable {
    case folder(Folder)
    case lidarr(Lidarr)
    /// A `kind` this version of the app doesn't know yet.
    case unknown(String)

    private enum TagKey: String, CodingKey { case kind = "kind" }

    public var kind: String {
        switch self {
        case .folder: "folder"
        case .lidarr: "lidarr"
        case .unknown(let value): value
        }
    }

    public init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .kind)
        switch tag {
        case "folder": self = .folder(try Folder(from: decoder))
        case "lidarr": self = .lidarr(try Lidarr(from: decoder))
        default: self = .unknown(tag)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .folder(let value): try value.encode(to: encoder)
        case .lidarr(let value): try value.encode(to: encoder)
        case .unknown: break
        }
        var container = encoder.container(keyedBy: TagKey.self)
        try container.encode(kind, forKey: .kind)
    }

    public struct Folder: Codable, Hashable, Sendable {
        /// What became of the file: matched (auto), waiting for review, or left with its own tags.
        public var state: State
        /// The song the file belongs to now (it changes when a match gives it its real MusicBrainz id).
        public var trackId: Int?

        public init(state: State, trackId: Int? = nil) {
            self.state = state
            self.trackId = trackId
        }

        public enum State: RawRepresentable, Codable, Hashable, Sendable, CaseIterable {
            case auto
            case manual
            case review
            case unmatched
            case ignored
            /// A value this version of the app doesn't know yet.
            case unknown(String)

            public static let allCases: [State] = [.auto, .manual, .review, .unmatched, .ignored]

            public init(rawValue: String) {
                switch rawValue {
                case "auto": self = .auto
                case "manual": self = .manual
                case "review": self = .review
                case "unmatched": self = .unmatched
                case "ignored": self = .ignored
                default: self = .unknown(rawValue)
                }
            }

            public var rawValue: String {
                switch self {
                case .auto: "auto"
                case .manual: "manual"
                case .review: "review"
                case .unmatched: "unmatched"
                case .ignored: "ignored"
                case .unknown(let value): value
                }
            }

            public init(from decoder: any Decoder) throws {
                self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.singleValueContainer()
                try container.encode(rawValue)
            }
        }
    }

    public struct Lidarr: Codable, Hashable, Sendable {
