/// How far a transition being made has got: waiting its turn (behind `ahead` others), decoding the two songs around the mix, mixing them, saving the file, then (for an MP3 next song) saving the rest of it. `done` is the whole job's share done, 0–1, the steps weighted by about how long each takes.
public struct RenderProgress: Codable, Hashable, Sendable {
    public var step: Step
    public var done: Double
    public var ahead: Double?

    public init(step: Step, done: Double, ahead: Double? = nil) {
        self.step = step
        self.done = done
        self.ahead = ahead
    }

    public enum Step: RawRepresentable, Codable, Hashable, Sendable, CaseIterable {
        case waiting
        case decoding
        case mixing
        case saving
        case savingTheRestOfTheNextSong
        /// A value this version of the app doesn't know yet.
        case unknown(String)

        public static let allCases: [Step] = [.waiting, .decoding, .mixing, .saving, .savingTheRestOfTheNextSong]

        public init(rawValue: String) {
            switch rawValue {
            case "waiting": self = .waiting
            case "decoding": self = .decoding
            case "mixing": self = .mixing
            case "saving": self = .saving
            case "saving the rest of the next song": self = .savingTheRestOfTheNextSong
            default: self = .unknown(rawValue)
            }
        }

        public var rawValue: String {
            switch self {
            case .waiting: "waiting"
            case .decoding: "decoding"
            case .mixing: "mixing"
            case .saving: "saving"
            case .savingTheRestOfTheNextSong: "saving the rest of the next song"
            case .unknown(let value): value
            }
        }

        public init(from decoder: any Decoder) throws {
            self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
        }

        public func encode(to encoder: any Encoder) throws {
            var container = encoder.singleValueContainer()
            try container.encode(rawValue)
        }
    }
}

