        self.albumId = albumId
        self.albumMbid = albumMbid
        self.releaseDate = releaseDate
        self.albumType = albumType
        self.secondaryTypes = secondaryTypes
        self.genres = genres
        self.artistId = artistId
        self.artistMbid = artistMbid
        self.copies = copies
        self.analysis = analysis
        self.pathsHidden = pathsHidden
    }

    public struct Analysis: Codable, Hashable, Sendable {
        /// Tempo, and how sure the beat is (0–1): from beat analysis, once the song has one.
        public var bpm: Double?
        public var pulse: Double?
        public var loudness: Double
        public var dynamics: Double
        public var brightness: Double
        public var busyness: Double
        public var bass: Double

        public init(bpm: Double? = nil, pulse: Double? = nil, loudness: Double, dynamics: Double, brightness: Double, busyness: Double, bass: Double) {
            self.bpm = bpm
            self.pulse = pulse
            self.loudness = loudness
            self.dynamics = dynamics
            self.brightness = brightness
            self.busyness = busyness
            self.bass = bass
        }
    }
}

/// POST /api/transitions: the file to play (ready), still rendering (pending, ask again), better played straight on, or not possible (no mix map yet, say).
public enum TransitionAnswer: Codable, Hashable, Sendable {
    case ready(Ready)
    case pending(Pending)
    case straight(Straight)
    case unavailable(Unavailable)
    /// A `status` this version of the app doesn't know yet.
    case unknown(String)

    private enum TagKey: String, CodingKey { case status = "status" }

    public var status: String {
        switch self {
        case .ready: "ready"
        case .pending: "pending"
        case .straight: "straight"
        case .unavailable: "unavailable"
        case .unknown(let value): value
        }
    }

    public init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .status)
        switch tag {
        case "ready": self = .ready(try Ready(from: decoder))
        case "pending": self = .pending(try Pending(from: decoder))
        case "straight": self = .straight(try Straight(from: decoder))
        case "unavailable": self = .unavailable(try Unavailable(from: decoder))
        default: self = .unknown(tag)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .ready(let value): try value.encode(to: encoder)
        case .pending(let value): try value.encode(to: encoder)
        case .straight(let value): try value.encode(to: encoder)
        case .unavailable(let value): try value.encode(to: encoder)
        case .unknown: break
        }
        var container = encoder.container(keyedBy: TagKey.self)
        try container.encode(status, forKey: .status)
    }

    public struct Ready: Codable, Hashable, Sendable {
        public var plan: TransitionPlan
        public var url: String
        public var continuationUrl: String?
        /// Seconds of B after the transition in its file (see TRANSITION_TAIL_SECONDS); none in older files.
        public var tail: Double?
        /// Seconds of A before the transition in its file: the file starts at plan.aStart − lead. None in older files.
        public var lead: Double?
        /// The songs' gains (dB) made into the audio (and B's remainder), when they were asked for.
        public var levels: Levels?

        public init(plan: TransitionPlan, url: String, continuationUrl: String? = nil, tail: Double? = nil, lead: Double? = nil, levels: Levels? = nil) {
            self.plan = plan
            self.url = url
            self.continuationUrl = continuationUrl
            self.tail = tail
            self.lead = lead
            self.levels = levels
        }

        public struct Levels: Codable, Hashable, Sendable {
            public var a: Double
            public var b: Double

            public init(a: Double, b: Double) {
                self.a = a
                self.b = b
            }
        }
    }

    public struct Pending: Codable, Hashable, Sendable {
        public var plan: TransitionPlan
        public var render: RenderProgress?

        public init(plan: TransitionPlan, render: RenderProgress? = nil) {
            self.plan = plan
            self.render = render
        }
    }

    public struct Straight: Codable, Hashable, Sendable {
        public var plan: TransitionPlan

        public init(plan: TransitionPlan) {
            self.plan = plan
        }
    }

    public struct Unavailable: Codable, Hashable, Sendable {
        public var reason: String

        public init(reason: String) {
            self.reason = reason
        }
    }
}

public struct TransitionPlan: Codable, Hashable, Sendable {
    public var style: TransitionStyle
    /// Where in A the transition starts (A plays normally until here).
    public var aStart: Double
    /// Where in B the transition starts.
    public var bStart: Double
    /// Seconds of transition output. It can run past A's end (a long blend's ease-back is B alone): A's gain is 0 by then, so the renderer treats A as silent past its end.
    public var length: Double
    /// Where in B normal playback resumes after the transition.
    public var bResume: Double
    /// Seconds into the transition where the listener hears B take over (lock screen switches here).
    public var switchAt: Double
    /// B's playback rate over the transition (1 = its own tempo), per point; A always plays at 1.
    public var bRate: Automation
    public var aGain: Automation
    public var bGain: Automation
    /// Low-shelf gain in dB on each side (0 = flat, −24 = bass gone): the bass swap.
    public var aLowDb: Automation
    public var bLowDb: Automation
    /// High-pass cutoff in Hz on A (20 = off): the quick-mix sweep.
    public var aHighPassHz: Automation
    /// Why this style: for the transition view and logs.
    public var reason: String
    /// Beats of A in the move, for the transition view: the overlap for a long blend (not B's ease-back after it), the lead-in up to the landing (8 or 4) for a quick mix, cuts included; 0 for a fade or straight on.
    public var beats: Double

    public init(style: TransitionStyle, aStart: Double, bStart: Double, length: Double, bResume: Double, switchAt: Double, bRate: Automation, aGain: Automation, bGain: Automation, aLowDb: Automation, bLowDb: Automation, aHighPassHz: Automation, reason: String, beats: Double) {
        self.style = style
        self.aStart = aStart
        self.bStart = bStart
        self.length = length
        self.bResume = bResume
        self.switchAt = switchAt
        self.bRate = bRate
        self.aGain = aGain
        self.bGain = bGain
        self.aLowDb = aLowDb
        self.bLowDb = bLowDb
        self.aHighPassHz = aHighPassHz
        self.reason = reason
        self.beats = beats
    }
}

public enum TransitionStyle: RawRepresentable, Codable, Hashable, Sendable, CaseIterable {
    case straight
    case long
    case quick
    case fade
    /// A value this version of the app doesn't know yet.
    case unknown(String)

    public static let allCases: [TransitionStyle] = [.straight, .long, .quick, .fade]

    public init(rawValue: String) {
        switch rawValue {
        case "straight": self = .straight
        case "long": self = .long
        case "quick": self = .quick
        case "fade": self = .fade
        default: self = .unknown(rawValue)
        }
    }

    public var rawValue: String {
        switch self {
        case .straight: "straight"
        case .long: "long"
        case .quick: "quick"
        case .fade: "fade"
        case .unknown(let value): value
        }
    }

    public init(from decoder: any Decoder) throws {
        self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }
}

public struct UpdateInfo: Codable, Hashable, Sendable {
    public var enabled: Bool
    public var intervalMinutes: UpdateInterval
    /// Updates can be managed here (Docker setup with the updater running).
    public var available: Bool
    /// Why not, when not.
    public var reason: String?
    public var status: Status?
    /// A Check now is waiting for the updater.
    public var requested: Bool
    /// The last run's output (update.sh), last 60 lines.
    public var log: String?

    public init(enabled: Bool, intervalMinutes: UpdateInterval, available: Bool, reason: String? = nil, status: Status? = nil, requested: Bool, log: String? = nil) {
        self.enabled = enabled
        self.intervalMinutes = intervalMinutes
        self.available = available
        self.reason = reason
        self.status = status
        self.requested = requested
        self.log = log
    }

    public struct Status: Codable, Hashable, Sendable {
        public var state: State
        /// Unix seconds. 0: never.
        public var lastCheck: Int
        public var lastUpdate: Int
        /// Commit running (full SHA), and the newest on GitHub main, when known.
        public var deployed: String?
        public var latest: String?
        public var error: String?

        public init(state: State, lastCheck: Int, lastUpdate: Int, deployed: String? = nil, latest: String? = nil, error: String? = nil) {
            self.state = state
            self.lastCheck = lastCheck
            self.lastUpdate = lastUpdate
            self.deployed = deployed
            self.latest = latest
            self.error = error
        }

        public enum State: RawRepresentable, Codable, Hashable, Sendable, CaseIterable {
            case idle
            case checking
            case failed
            /// A value this version of the app doesn't know yet.
            case unknown(String)

            public static let allCases: [State] = [.idle, .checking, .failed]

            public init(rawValue: String) {
                switch rawValue {
                case "idle": self = .idle
                case "checking": self = .checking
                case "failed": self = .failed
                default: self = .unknown(rawValue)
                }
            }

            public var rawValue: String {
                switch self {
                case .idle: "idle"
                case .checking: "checking"
                case .failed: "failed"
                case .unknown(let value): value
                }
            }

            public init(from decoder: any Decoder) throws {
                self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.singleValueContainer()
                try container.encode(rawValue)
            }
        }
    }
}

/// Settings → Updates: how often the updater container checks GitHub main.
public typealias UpdateInterval = Int

/// What Settings → Updates can change. Not the repository, branch or commit: only main of the configured repository is deployed.
public struct UpdateSettings: Codable, Hashable, Sendable {
    public var enabled: Bool
    public var intervalMinutes: UpdateInterval

    public init(enabled: Bool, intervalMinutes: UpdateInterval) {
        self.enabled = enabled
        self.intervalMinutes = intervalMinutes
    }
}

/// PUT /api/settings/updates: the settings to change.
public struct UpdateSettingsPatch: Codable, Hashable, Sendable {
    public var enabled: Bool?
    public var intervalMinutes: UpdateInterval?

    public init(enabled: Bool? = nil, intervalMinutes: UpdateInterval? = nil) {
        self.enabled = enabled
        self.intervalMinutes = intervalMinutes
    }
}
